document.addEventListener('click',e=>{const b=e.target.closest('#prepareContactEmail');const a=e.target.closest('a');if(b||(a&&/^(mailto:|tel:)/.test(a.getAttribute('href')||''))){e.preventDefault();e.stopImmediatePropagation();alert('Gestaltungsvorschau: Es wird keine Kontaktanfrage geöffnet oder gesendet. Nutze dafür die bestehende Website.');}},true);document.addEventListener('DOMContentLoaded',()=>{document.querySelectorAll('a[href^="https:"]').forEach(a=>{if(a.origin!==location.origin){a.target='_blank';a.rel='noopener noreferrer';}});});
document.addEventListener('DOMContentLoaded',()=>{if(!location.pathname.includes('/kontakt/'))return;const role=document.querySelector('[name="role"]');const learner=new URLSearchParams(location.search).get('zielgruppe')==='learner';if(role&&learner){role.value='Fahrschüler:in';role.dispatchEvent(new Event('change',{bubbles:true}));const h=document.querySelector('.contact-page-hero h1');if(h)h.textContent='Deine Frage. Dein nächster Schritt.';const topic=document.querySelector('[name="topic"]');if(topic)topic.value='Unfallabsicherung und erstes Auto';} });
